const offline=location.protocol==='file:';$('#offline-note').hidden=!offline;
$('#download-cards').innerHTML=downloads.filter(d=>!offline||!d.path.endsWith('.zip')).map(d=>`<article class="download-card"><div><h4>${esc(d.title)}</h4><p>${esc(d.description)}</p><span class="download-size">${(d.bytes/1048576).toFixed(2)} MB · SHA ${d.sha256.slice(0,12)}…</span></div><a href="${d.path}" download aria-label="下载${esc(d.title)}">↓</a></article>`).join('');
if(offline)$('#download-cards').innerHTML='<p class="fine">已解压的完整结果在data目录；可使用下方CSV、JSON与校验清单。</p>';
