const nav=$$('.sidebar nav a'),sections=nav.map(a=>$(a.getAttribute('href'))).filter(Boolean);function activeSection(){let current=sections[0];for(const s of sections){if(s.getBoundingClientRect().top<=170)current=s;}nav.forEach(a=>{const active=a.getAttribute('href')==='#'+current.id;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});}let scheduled=false;document.addEventListener('scroll',()=>{if(!scheduled){scheduled=true;requestAnimationFrame(()=>{activeSection();scheduled=false;});}},{passive:true});activeSection();
window.RESEARCH_UI={conditionCount:D.conditions.length,frameCurve,displayIndices,auc,renderCase,showCondition,metricNames};
